#!/bin/bash
# Regenerate the app mark and everything derived from it.
#
#   tool/generate_app_icons.sh
#
# Why this exists: the icons were once edited as PNGs (and the 21 sizes were
# regenerated by a tool that also wanted an Android project that this branch does
# not carry). The mark is now a checked-in SVG, and this script is the only way
# the PNGs are produced — so "regenerate" means rerun this, not "replace the big
# one and hope the small ones follow".
#
# Outputs:
#   assets/images/logo/logo.png     1024×1024, opaque      (iOS / macOS / README)
#   assets/images/logo/logo_2.png   1024×1024, transparent (Android foreground, splash)
#   ios/Runner/Assets.xcassets/AppIcon.appiconset/*.png   21 sizes
#   ios/Runner/Assets.xcassets/LaunchImage.imageset/*.png 6 images (light + dark)
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

CHROME="${CHROME:-/Applications/Google Chrome.app/Contents/MacOS/Google Chrome}"
[[ -x "$CHROME" ]] || { echo "BLOCKED_TOOLING: Chrome not found at $CHROME" >&2; exit 4; }

MARK="assets/images/logo/bilibiliplus-mark.svg"
MARK_T="assets/images/logo/bilibiliplus-mark-transparent.svg"
[[ -f "$MARK" && -f "$MARK_T" ]] || { echo "BLOCKED: mark SVG missing" >&2; exit 5; }

render() { # <svg> <out> <opaque|transparent>
  local svg="$1" out="$2" mode="$3"
  # Two explicit invocations rather than an optional-argument array: macOS ships
  # bash 3.2, where an empty array under `set -u` is an unbound variable.
  if [[ "$mode" == "transparent" ]]; then
    "$CHROME" --headless --disable-gpu --hide-scrollbars \
      --window-size=1024,1024 --force-device-scale-factor=1 \
      --default-background-color=00000000 \
      --screenshot="$out" "file://$ROOT/$svg" >/dev/null 2>&1
  else
    "$CHROME" --headless --disable-gpu --hide-scrollbars \
      --window-size=1024,1024 --force-device-scale-factor=1 \
      --screenshot="$out" "file://$ROOT/$svg" >/dev/null 2>&1
  fi
  [[ -f "$out" ]] || { echo "BLOCKED: rendering $svg failed" >&2; exit 6; }
}

echo "== 1. masters =="
render "$MARK"   "assets/images/logo/logo.png"   opaque
render "$MARK_T" "assets/images/logo/logo_2.png" transparent
for f in assets/images/logo/logo.png assets/images/logo/logo_2.png; do
  printf '  %-38s %s  %s\n' "$f" \
    "$(sips -g pixelWidth "$f" | awk '/pixelWidth/{print $2}')x$(sips -g pixelHeight "$f" | awk '/pixelHeight/{print $2}')" \
    "alpha=$(sips -g hasAlpha "$f" | awk '/hasAlpha/{print $2}')"
done

echo "== 2. iOS app icons (21 sizes) =="
# flutter_launcher_icons reads flutter_launcher_icons.yaml when it exists, which
# pins this run to iOS: android/ is not part of this branch, and the tool aborts
# when it cannot find AndroidManifest.xml.
dart run flutter_launcher_icons | tail -3
COUNT=$(ls ios/Runner/Assets.xcassets/AppIcon.appiconset/*.png | wc -l | tr -d ' ')
[[ "$COUNT" = "21" ]] || { echo "BLOCKED: expected 21 icons, found $COUNT" >&2; exit 7; }
echo "  $COUNT icons regenerated"

echo "== 3. launch images (light + dark) =="
L=ios/Runner/Assets.xcassets/LaunchImage.imageset
for spec in "LaunchImage.png:128" "LaunchImage@2x.png:256" "LaunchImage@3x.png:384" \
            "LaunchImageDark.png:128" "LaunchImageDark@2x.png:256" "LaunchImageDark@3x.png:384"; do
  f="${spec%%:*}"; s="${spec##*:}"
  sips -z "$s" "$s" assets/images/logo/logo_2.png --out "$L/$f" >/dev/null
  printf '  %-26s %sx%s\n' "$f" "$s" "$s"
done

echo "== 4. desktop window icon + .ico =="
# Two more consumers of the same mark: the desktop window icon (logo_large.png)
# and the Windows .ico. Leaving them on the old artwork is exactly the stale-image
# problem this script exists to prevent.
sips -z 512 512 assets/images/logo/logo.png --out assets/images/logo/desktop/logo_large.png >/dev/null
PY="${PYTHON:-python3}"
"$PY" - <<'PYEOF'
import sys
from PIL import Image
src = Image.open('assets/images/logo/logo.png').convert('RGBA')
sizes = [(16,16),(24,24),(32,32),(48,48),(64,64),(128,128),(256,256)]
src.save('assets/images/logo/ico/app_icon.ico', sizes=sizes)
print('  app_icon.ico', ', '.join(f'{w}x{h}' for w, h in sizes))
PYEOF

echo "== 5. identity =="
shasum -a 256 assets/images/logo/logo.png assets/images/logo/logo_2.png \
  assets/images/logo/desktop/logo_large.png assets/images/logo/ico/app_icon.ico \
  ios/Runner/Assets.xcassets/AppIcon.appiconset/Icon-App-1024x1024@1x.png \
  ios/Runner/Assets.xcassets/AppIcon.appiconset/Icon-App-60x60@3x.png | sed 's/^/  /'
echo "ICONS_REGENERATED"
